package dev.phantom.ac;

import static dev.phantom.ac.Maths.Vec3;
import static dev.phantom.ac.Packets.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;

class Phase7TimingScenarioMatrixTest {
  private static Timeline.Snapshot timeline(RawPacket... packets){return Timeline.assign(new Normalizer().normalize(List.of(packets)),0,50_000_000L);}
  private static Phase7Timing.Config config(long up,long down){return new Phase7Timing.Config(50_000_000L,50_000_000L,50_000_000L,new Phase7Timing.LatencyBounds(0,up),new Phase7Timing.LatencyBounds(0,down),new Phase7Timing.TickDelayBounds(0,1),new Phase7Timing.TickDelayBounds(0,1),250_000_000L,3,128);}
  private static void deterministic(Timeline.Snapshot t,Phase7Timing.Config c){assertEquals(Phase7Timing.reconstruct(t,c).canonicalText(),Phase7Timing.reconstruct(t,c).canonicalText());}
  @Test void lowLatencyAndStableLatencyAreRepresented(){var low=Phase7Timing.reconstruct(timeline(new RawPacket(1,0,new Move(Vec3.ZERO,0f,0f,true,0L)),new RawPacket(2,50_000_000L,new Move(new Vec3(.1,0,0),0f,0f,true,1L))),config(1_000_000L,1_000_000L));var stable=Phase7Timing.reconstruct(timeline(new RawPacket(1,0,new Move(Vec3.ZERO,0f,0f,true,0L)),new RawPacket(2,50_000_000L,new Move(new Vec3(.1,0,0),0f,0f,true,1L))),config(25_000_000L,25_000_000L));assertEquals(2,low.frames().size());assertEquals(2,stable.frames().size());deterministic(timeline(new RawPacket(1,0,new Move(Vec3.ZERO,0f,0f,true,0L))),config(0,0));}
  @Test void latencyPlusJitterPlusCorrectionNeverCreatesImpossibleTimingVerdict(){var r=Phase7Timing.reconstruct(timeline(new RawPacket(1,0,new Move(Vec3.ZERO,0f,0f,true,0L)),new RawPacket(2,50_000_000L,new Teleport(7,Vec3.ZERO,0f,0f)),new RawPacket(3,95_000_000L,new TeleportConfirm(7)),new RawPacket(4,155_000_000L,new Move(new Vec3(.1,0,0),0f,0f,true,null))),config(40_000_000L,40_000_000L));assertEquals(Phase7Timing.Consistency.UNCERTAIN,r.consistency());assertTrue(r.finalState().status()!=Phase7Timing.SyncStatus.SYNCHRONIZED);}
  @Test void latencyPlusVelocityCreatesTimingWindow(){var r=Phase7Timing.reconstruct(timeline(new RawPacket(1,0,new Move(Vec3.ZERO,0f,0f,true,0L)),new RawPacket(2,50_000_000L,new Velocity(new Vec3(.4,.2,0))),new RawPacket(3,110_000_000L,new Move(new Vec3(.4,.2,0),0f,0f,false,null))),config(30_000_000L,30_000_000L));assertTrue(r.timingFor(2).orElseThrow().windows().stream().anyMatch(w->w.kind()==Phase7Timing.WindowKind.VELOCITY));assertTrue(r.timingFor(2).orElseThrow().uncertain());}
  @Test void burstPlusJitterPreservesEveryMovementPacket(){var t=timeline(new RawPacket(1,100_000_000L,new Move(Vec3.ZERO,0f,0f,true,0L)),new RawPacket(2,100_000_001L,new Move(new Vec3(.05,0,0),0f,0f,true,null)),new RawPacket(3,100_000_002L,new Move(new Vec3(.10,0,0),0f,0f,true,null)),new RawPacket(4,140_000_000L,new Move(new Vec3(.15,0,0),0f,0f,true,null)));var r=Phase7Timing.reconstruct(t,config(20_000_000L,20_000_000L));assertEquals(4,r.frames().size());assertEquals(List.of(1L,2L,3L,4L),r.frames().stream().map(f->f.timing().sequence()).toList());}
  @Test void worldUpdatePlusMovementRemainsConservative(){var t=timeline(new RawPacket(1,0,new Move(Vec3.ZERO,0f,0f,true,0L)),new RawPacket(2,45_000_000L,new ChunkData(new World.Chunk(0,0),Map.of())),new RawPacket(3,90_000_000L,new Move(new Vec3(.1,0,0),0f,0f,true,null)));var r=Phase7Timing.reconstruct(t,config(25_000_000L,50_000_000L));assertTrue(r.timingFor(2).orElseThrow().windows().stream().anyMatch(w->w.kind()==Phase7Timing.WindowKind.WORLD_UPDATE));assertTrue(r.timingFor(3).orElseThrow().uncertain());}
  @Test void packetGapPlusCorrectionEntersRecovery(){var t=timeline(new RawPacket(1,0,new Move(Vec3.ZERO,0f,0f,true,0L)),new RawPacket(2,400_000_000L,new Teleport(7,new Vec3(1,1,1),0f,0f)));var r=Phase7Timing.reconstruct(t,config(0,0));assertEquals(Phase7Timing.SyncStatus.RECOVERING,r.finalState().status());assertTrue(r.frames().get(1).timing().windows().stream().anyMatch(w->w.kind()==Phase7Timing.WindowKind.PACKET_GAP));assertTrue(r.frames().get(1).timing().windows().stream().anyMatch(w->w.kind()==Phase7Timing.WindowKind.TELEPORT));}
  @Test void missingObservationDoesNotBecomeIdleInference(){var r=Phase7Timing.reconstruct(timeline(new RawPacket(1,0,new Move(Vec3.ZERO,0f,0f,true,0L)),new RawPacket(2,300_000_000L,new Move(new Vec3(3,0,0),0f,0f,true,null))),config(0,0));assertTrue(r.frames().get(1).timing().reasons().stream().anyMatch(s->s.contains("does not imply client inactivity")));assertNotEquals(Phase7Timing.SyncStatus.SYNCHRONIZED,r.finalState().status());}
  @Test void reorderedSequenceIsNeverSilentlyRewritten(){var t=timeline(new RawPacket(1,0,new Move(Vec3.ZERO,0f,0f,true,0L)),new RawPacket(3,50_000_000L,new Move(new Vec3(.3,0,0),0f,0f,true,3L)),new RawPacket(2,60_000_000L,new Move(new Vec3(.2,0,0),0f,0f,true,2L)));var r=Phase7Timing.reconstruct(t,config(0,0));assertEquals(List.of(1L,3L,2L),r.frames().stream().map(f->f.timing().sequence()).toList());assertTrue(r.frames().get(2).timing().windows().stream().anyMatch(w->w.kind()==Phase7Timing.WindowKind.REORDERING));}
  @Test void wideTimingEnvelopeIsBoundedBeforePhase6(){var c=config(100_000_000L,100_000_000L);var t=timeline(new RawPacket(1,0,new Move(Vec3.ZERO,0f,0f,true,0L)),new RawPacket(2,1_000_000_000L,new Move(new Vec3(1,0,0),0f,0f,true,null)));var r=Phase7Timing.reconstruct(t,c);var timing=r.frames().get(1).timing();assertTrue(timing.simulationClientTicks().width()>=1);assertTrue(timing.uncertain());}
  @Test void directionSpecificLatencyIsKeptSeparate(){var r=Phase7Timing.reconstruct(timeline(new RawPacket(1,100_000_000L,new Move(Vec3.ZERO,0f,0f,true,0L)),new RawPacket(2,100_000_000L,new Velocity(Vec3.ZERO))),config(60_000_000L,10_000_000L));assertEquals(new Phase7Timing.TimeRange(40_000_000L,100_000_000L),r.frames().get(0).timing().packetGenerationNanos());assertEquals(new Phase7Timing.TimeRange(100_000_000L,110_000_000L),r.frames().get(1).timing().clientProcessingNanos());}
}
